// Expande y abrevia direcciones IPv6 con las reglas del RFC 5952
function expandir(texto) {
  const [izq, der] = texto.includes("::") ? texto.split("::") : [texto, null];
  const a = izq ? izq.split(":") : [];
  const b = der ? der.split(":") : [];
  const relleno = der === null ? [] : Array(8 - a.length - b.length).fill("0");
  return [...a, ...relleno, ...b].map(g => g.padStart(4, "0").toLowerCase());
}

function abreviar(texto) {
  const g = expandir(texto).map(x => x.replace(/^0+(?=.)/, ""));
  let mejor = { ini: -1, len: 0 };
  for (let i = 0; i < 8; ) {
    if (g[i] !== "0") { i++; continue; }
    let j = i;
    while (j < 8 && g[j] === "0") j++;
    if (j - i > mejor.len) mejor = { ini: i, len: j - i };  // empate: gana la primera
    i = j;
  }
  if (mejor.len < 2) return g.join(":");                    // un solo grupo en cero no se abrevia
  return g.slice(0, mejor.ini).join(":") + "::" + g.slice(mejor.ini + mejor.len).join(":");
}

